<?php
require_once __DIR__.'/config/config.php'; require_login();
$pageTitle='Informes'; $active='informes';$desde=$_GET['desde']??date('Y-m-01');$hasta=$_GET['hasta']??date('Y-m-d');$rows=[];$summary=['ventas'=>0,'impuestos'=>0,'costo'=>0,'abonado'=>0,'gastos'=>0];
try{$pdo=db();$st=$pdo->prepare("SELECT DATE(v.fecha) dia,COUNT(*) cantidad,SUM(CASE WHEN v.estado<>'Anulada' THEN v.subtotal ELSE 0 END) subtotal,SUM(CASE WHEN v.estado<>'Anulada' THEN v.impuestos ELSE 0 END) impuestos,SUM(CASE WHEN v.estado<>'Anulada' THEN v.total ELSE 0 END) total,SUM(CASE WHEN v.estado<>'Anulada' THEN v.abonado ELSE 0 END) abonado FROM ventas v WHERE DATE(v.fecha) BETWEEN ? AND ? GROUP BY DATE(v.fecha) ORDER BY dia DESC");$st->execute([$desde,$hasta]);$rows=$st->fetchAll();$st=$pdo->prepare("SELECT COALESCE(SUM(CASE WHEN estado<>'Anulada' THEN total ELSE 0 END),0) ventas,COALESCE(SUM(CASE WHEN estado<>'Anulada' THEN impuestos ELSE 0 END),0) impuestos,COALESCE(SUM(CASE WHEN estado<>'Anulada' THEN abonado ELSE 0 END),0) abonado,COALESCE(SUM(CASE WHEN estado<>'Anulada' THEN (SELECT COALESCE(SUM(d.cantidad*d.costo_unitario),0) FROM venta_detalles d WHERE d.venta_id=ventas.id) ELSE 0 END),0) costo FROM ventas WHERE DATE(fecha) BETWEEN ? AND ?");$st->execute([$desde,$hasta]);$summary=array_merge($summary,$st->fetch());$st=$pdo->prepare('SELECT COALESCE(SUM(valor),0) FROM gastos WHERE fecha BETWEEN ? AND ?');$st->execute([$desde,$hasta]);$summary['gastos']=$st->fetchColumn();}catch(Throwable $ex){}
include __DIR__.'/includes/header.php';
?>
<section class="filter-panel"><form class="filter-form" method="get"><label>Fecha inicial<input type="date" name="desde" value="<?=e($desde)?>"></label><label>Fecha final<input type="date" name="hasta" value="<?=e($hasta)?>"></label><button class="btn primary">Generar informe</button><button class="btn light" type="button" onclick="window.print()">Imprimir / Guardar PDF</button></form></section>
<section class="stats-grid"><div class="stat-card"><div class="stat-icon">▤</div><div><div class="stat-label">VENTAS FACTURADAS</div><div class="stat-value"><?=money($summary['ventas'])?></div></div></div><div class="stat-card"><div class="stat-icon">▦</div><div><div class="stat-label">IMPUESTOS</div><div class="stat-value"><?=money($summary['impuestos'])?></div></div></div><div class="stat-card"><div class="stat-icon">↗</div><div><div class="stat-label">UTILIDAD BRUTA ESTIMADA</div><div class="stat-value"><?=money($summary['ventas']-$summary['impuestos']-$summary['costo'])?></div></div></div><div class="stat-card"><div class="stat-icon">▧</div><div><div class="stat-label">GASTOS</div><div class="stat-value"><?=money($summary['gastos'])?></div></div></div><div class="stat-card stat-highlight"><div class="stat-icon">$</div><div><div class="stat-label">ABONOS REGISTRADOS</div><div class="stat-value"><?=money($summary['abonado'])?></div></div></div></section>
<section class="table-panel"><div class="table-toolbar"><b>Resumen diario</b><span class="muted small"><?=e($desde)?> al <?=e($hasta)?></span></div><div class="table-scroll"><table><thead><tr><th>Fecha</th><th class="numeric">N.º ventas</th><th class="numeric">Subtotal</th><th class="numeric">Impuestos</th><th class="numeric">Total</th><th class="numeric">Abonado</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e(date('d/m/Y',strtotime($r['dia'])))?></td><td class="numeric"><?=e($r['cantidad'])?></td><td class="numeric"><?=money($r['subtotal'])?></td><td class="numeric"><?=money($r['impuestos'])?></td><td class="numeric"><?=money($r['total'])?></td><td class="numeric"><?=money($r['abonado'])?></td></tr><?php endforeach;if(!$rows): ?><tr><td colspan="6" class="empty">No hay ventas en el período seleccionado.</td></tr><?php endif; ?></tbody></table></div></section>
<?php include __DIR__.'/includes/footer.php'; ?>
